<script>
document.addEventListener('click', function (e) {
  var b = e.target.closest('[data-cb-id]');
  if (b) { document.getElementById('cb-id').value = b.getAttribute('data-cb-id'); document.getElementById('cb-name').textContent = b.getAttribute('data-cb-name'); }
  var r = e.target.closest('#cb-dialog .cb-r');
  if (r) { document.getElementById('cb-reason').value = r.getAttribute('data-reason'); }
});
